import{_ as d,o,c as a,a2 as r}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"توسیعی ترتیبات کی تجاویز کی فہرست","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0098-扩展设定建议清单.md","filePath":"ur/0098-扩展设定建议清单.md"}'),h={name:"ur/0098-扩展设定建议清单.md"};function e(u,t,q,l,i,n){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="توسیعی-ترتیبات-کی-تجاویز-کی-فہرست" tabindex="-1">توسیعی ترتیبات کی تجاویز کی فہرست <a class="header-anchor" href="#توسیعی-ترتیبات-کی-تجاویز-کی-فہرست" aria-label="Permalink to &quot;توسیعی ترتیبات کی تجاویز کی فہرست&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>98</td></tr><tr><td>ماڈیول</td><td>ضمیمے اور حوالہ جاتی مواد</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>توسیعی ترتیبات، تخلیقی تجاویز، ترتیب کی سمت، کھلا پن، ترقی یافتہ شعبے</td></tr></tbody></table><h2 id="_1-تفصیل" tabindex="-1">1. تفصیل <a class="header-anchor" href="#_1-تفصیل" aria-label="Permalink to &quot;1. تفصیل&quot;">​</a></h2><p>یہ دستاویز اینکر سمبیوسس تہذیب کے ترتیب کے نظام میں توسیعی تخلیق کے لیے دستیاب سمتوں اور تجاویز کی فہرست دیتا ہے، جس کا مقصد ترتیب تخلیق کاروں کو تحریک اور رہنمائی فراہم کرنا ہے، اور انہیں موجودہ فریم ورک کے اندر قیمتی ترتیب کی توسیع کرنے میں مدد کرنا ہے۔ یہ فہرست ماڈیول کے لحاظ سے درجہ بندی کی گئی ہے، اور ہر توسیعی سمت میں سمت کی تفصیل، توسیع کی قدر، موجودہ ترتیبات کے ساتھ تعلق اور تخلیقی تجاویز شامل ہیں۔ اس بات پر زور دینا ضروری ہے کہ یہ فہرست صرف تجویزی حوالہ ہے؛ تخلیق کار ترتیب کی مطابقت کی شرط پر آزادانہ کام کر سکتے ہیں، یا ایسی بالکل نئی سمتیں بھی تیار کر سکتے ہیں جو اس فہرست میں شامل نہیں ہیں۔ تمام توسیعی ترتیبات کو رسمی طور پر شامل کرنے سے پہلے دستاویز 97 &quot;ترتیبات کے تضاد کی خود جانچ کی جدول&quot; کی جانچ پاس کرنی ہوگی۔</p><h2 id="_2-عالمی-نظریہ-اور-بنیادی-ترتیبات-کی-توسیع-کی-سمت" tabindex="-1">2. عالمی نظریہ اور بنیادی ترتیبات کی توسیع کی سمت <a class="header-anchor" href="#_2-عالمی-نظریہ-اور-بنیادی-ترتیبات-کی-توسیع-کی-سمت" aria-label="Permalink to &quot;2. عالمی نظریہ اور بنیادی ترتیبات کی توسیع کی سمت&quot;">​</a></h2><table tabindex="0"><thead><tr><th>نمبر</th><th>توسیع کی سمت</th><th>توسیع کی قدر</th><th>متعلقہ ترتیب</th><th>تخلیقی تجویز</th></tr></thead><tbody><tr><td>E01</td><td>کائنات کی حدود سے باہر کا وجود</td><td>ہینگیوانژو کے قانون کے نیٹ ورک سے باہر کوئی دوسرا کائنات یا اعلیٰ جہت کا وجود ہے یا نہیں، اس کی کھوج کرنا، ترتیب کے لیے زیادہ شاندار کائناتی نظریہ فراہم کرنا</td><td>دستاویز 00، دستاویز 28</td><td>&quot;کائنات کی دیوار&quot; کے وجود اور کائنات کی دیوار کو توڑنے والے چند متلاشیوں کی کہانیاں ترتیب دی جا سکتی ہیں، جو مستقبل میں کائناتوں کے درمیان تعامل کے لیے اشارے چھوڑ دیں گی</td></tr><tr><td>E02</td><td>کائنات کی مرضی کا جوہر</td><td>قانون کے نیٹ ورک کی نچلی تہہ میں کوئی &quot;کائنات کی مرضی&quot; ہے یا نہیں اور اس کا اینکر کے طریقہ کار سے تعلق، گہرائی سے بحث کرنا</td><td>دستاویز 00، دستاویز 20</td><td>کائنات کی مرضی کو ایک غیر شخصیت والے قانون کی خود تنظیمی رجحان کے طور پر ترتیب دیا جا سکتا ہے، کسی مخصوص دیوتا کے طور پر نہیں، &quot;حقیقت پر مبنی&quot; موقف کو برقرار رکھتے ہوئے</td></tr><tr><td>E03</td><td>اینکر سے پہلے کے دور کی کھوئی ہوئی تہذیبیں</td><td>اینکر سے پہلے کے دور میں ایک زمانے میں آباد رہی لیکن ختم ہو چکی تہذیبوں کی تفصیلی ترتیب، تاریخی گہرائی کو بھرپور بنانا</td><td>دستاویز 71، دستاویز 93</td><td>3-5 نمائندہ کھوئی ہوئی تہذیبیں ترتیب دی جا سکتی ہیں، ہر تہذیب کا اپنا منفرد سادنہ نظام، ثقافت اور ختم ہونے کی وجہ ہے، آثار قدیمہ کی ترتیب کے لیے مواد فراہم کرتا ہے</td></tr><tr><td>E04</td><td>سمبیوسس کے تصور کے فلسفیانہ مکاتب فکر</td><td>&quot;لوٹ مار کے خلاف، سمبیوسس کی وکالت&quot; کے بڑے فریم ورک کے تحت، مختلف فلسفیانہ مکاتب فکر کی سمبیوسس کے تصور کی مختلف تشریحات کو ترتیب دینا</td><td>دستاویز 04، دستاویز 03</td><td>&quot;انتہائی پسند سمبیوسس جماعت&quot;، &quot;معتدل سمبیوسس جماعت&quot;، &quot;ماحولیاتی سمبیوسس جماعت&quot;، &quot;ٹیکنالوجی سمبیوسس جماعت&quot; جیسی جماعتیں ترتیب دی جا سکتی ہیں، اور ان کے درمیان فکری تصادم اہم پلاٹ تناؤ بن سکتا ہے</td></tr></tbody></table><h2 id="_3-سادنہ-نظام-کی-توسیع-کی-سمت" tabindex="-1">3. سادنہ نظام کی توسیع کی سمت <a class="header-anchor" href="#_3-سادنہ-نظام-کی-توسیع-کی-سمت" aria-label="Permalink to &quot;3. سادنہ نظام کی توسیع کی سمت&quot;">​</a></h2><table tabindex="0"><thead><tr><th>نمبر</th><th>توسیع کی سمت</th><th>توسیع کی قدر</th><th>متعلقہ ترتیب</th><th>تخلیقی تجویز</th></tr></thead><tbody><tr><td>E05</td><td>ایک واحد نظام کی تفصیلی طریقہ</td><td>تین سو نظاموں میں سے کسی ایک کو تفصیل سے وسعت دینا، بشمول مخصوص سادنہ طریقہ، سطح سے نکلنے کا طریقہ، عام غلطیاں وغیرہ</td><td>دستاویز 10-19، دستاویز 91</td><td>تجویز ہے کہ پہلے بنیادی تین بنیادیں اور اطلاقی انجینئرنگ کے زمرے میں ٹیکنالوجی سے گہرا تعلق رکھنے والے نظاموں کو وسعت دی جائے؛ ہر نظام کی تفصیلی دستاویز میں سادنہ کے مراحل، ذہنی فارمولے، وسائل کی ضرورت، خطرے کی انتباہ وغیرہ شامل ہو سکتے ہیں</td></tr><tr><td>E06</td><td>نظاموں کے بیک وقت سادنہ کے امتزاج کا منصوبہ</td><td>مختلف نظاموں کے درمیان بیک وقت سادنہ کی مطابقت پر تحقیق کرنا اور بہترین کثیر النظام امتزاج کا منصوبہ ڈیزائن کرنا</td><td>دستاویز 10، دستاویز 11-13</td><td>&quot;سنہری امتزاج&quot; (جیسے تخمینہ کی تکرار + خلائی قوانین + اطلاقی انجینئرنگ) اور مختلف غیر معمولی امتزاج ترتیب دی جا سکتے ہیں، ہر امتزاج کے فوائد اور حدود کا تجزیہ کیا جا سکتا ہے</td></tr><tr><td>E07</td><td>سادنہ کی رکاوٹیں اور نکلنے کے طریقے</td><td>مختلف سطحوں پر ہر نظام کو درپیش ہونے والی رکاوٹوں کی تفصیلی ترتیب اور رکاوٹ سے نکلنے کے متعدد طریقے</td><td>دستاویز 14، دستاویز 19</td><td>&quot;داخلی شیطان کی آزمائش&quot;، &quot;قانون کی رکاوٹ&quot;، &quot;اصل کی رکاوٹ&quot; جیسی مختلف قسم کی رکاوٹیں اور متعلقہ نکلنے کے راستے ترتیب دی جا سکتے ہیں، سادنہ کے عمل کی سطح کو بڑھاتے ہوئے</td></tr><tr><td>E08</td><td>خاص جسمانی ساخت اور نظام کی موافقت</td><td>مختلف خاص جسمانی ساختوں (جیسے پیدائشی داؤ جسم، عنصری وابستہ جسم، شعوری حساس جسم وغیرہ) اور مختلف سادنہ نظاموں کے ساتھ ان کے تعلق کی موافقت کی ترتیب</td><td>دستاویز 12، دستاویز 51</td><td>ایک &quot;جسمانی ساخت-نظام کی موافقت میٹرکس&quot; ڈیزائن کیا جا سکتا ہے، جو تخلیق کاروں کو یہ فیصلہ کرنے میں مدد دیتا ہے کہ کسی خاص جسمانی ساخت کے لیے کون سے نظام موزوں ہیں</td></tr><tr><td>E09</td><td>سادنہ کے وسائل کی تفصیلی درجہ بندی</td><td>سادنہ کے لیے درکار مختلف وسائل (قدرتی خزانے، توانائی کے کرسٹل، قوانین کے ٹکڑے وغیرہ) کی تفصیلی درجہ بندی اور ترتیب</td><td>دستاویز 18، دستاویز 65</td><td>وسائل کی درجہ بندی، پیداوار کی جگہ، اکٹھا کرنے کا طریقہ، محفوظ رکھنے کا طریقہ، استعمال کی ممانعت وغیرہ ترتیب دی جا سکتی ہے، مکمل سادنہ وسائل ماحولیاتی نظام کی تعمیر</td></tr></tbody></table><h2 id="_4-سماجی-نظام-کی-توسیع-کی-سمت" tabindex="-1">4. سماجی نظام کی توسیع کی سمت <a class="header-anchor" href="#_4-سماجی-نظام-کی-توسیع-کی-سمت" aria-label="Permalink to &quot;4. سماجی نظام کی توسیع کی سمت&quot;">​</a></h2><table tabindex="0"><thead><tr><th>نمبر</th><th>توسیع کی سمت</th><th>توسیع کی قدر</th><th>متعلقہ ترتیب</th><th>تخلیقی تجویز</th></tr></thead><tbody><tr><td>E10</td><td>پانچ اقسام کی مخصوص سماجی شکلیں</td><td>پانچ قسم کی سمبیوسس تہذیبوں میں سے ہر ایک کی مخصوص سماجی نظام، معاشی ماڈل اور ثقافتی خصوصیات کو تفصیل سے وسعت دینا</td><td>دستاویز 30-35</td><td>ہر قسم کی اپنی مخصوص شہری شکل، خاندانی ساخت، تعلیمی ماڈل، تہواروں کی تقریبات وغیرہ ترتیب دی جا سکتی ہیں، جس سے پانچ اقسام میں سے ہر ایک کی اپنی خصوصیت ہو</td></tr><tr><td>E11</td><td>سمبیوسس شہر کی منصوبہ بندی اور تعمیر</td><td>سمبیوسس تہذیب میں شہروں کی منصوبہ بندی کے تصور، تعمیراتی انداز، بنیادی ڈھانچے اور فنکشنل علاقوں کی ترتیب</td><td>دستاویز 39، دستاویز 60</td><td>&quot;عمودی سمبیوسس شہر&quot;، &quot;ماحولیاتی گھوںسلا شہر&quot;، &quot;خلائی تہہ شہر&quot; جیسی مختلف قسم کی شہری شکلیں ڈیزائن کی جا سکتی ہیں</td></tr><tr><td>E12</td><td>تعلیمی نظام کی تفصیلی کارکردگی</td><td>پری اسکول سے لے کر اعلیٰ تعلیم اور سادنہ تعلیم تک سمبیوسس تعلیمی نظام کے مکمل کام کرنے کے طریقہ کار کی تفصیلی ترتیب</td><td>دستاویز 37، دستاویز 43</td><td>نصابی نظام، امتحان کے طریقے، اساتذہ کا نظام، بین الاقوامی تعلیم کے منصوبے وغیرہ ترتیب دی جا سکتے ہیں</td></tr><tr><td>E13</td><td>طبی نظام کی تفصیلی کارکردگی</td><td>عام طبی اور سادنہ طبی کے امتزاج سمیت سمبیوسس طبی نظام کے کام کرنے کے طریقہ کار کی تفصیلی ترتیب</td><td>دستاویز 38، دستاویز 44</td><td>ہسپتال کا نظام، ہیلتھ انشورنس کی ادائیگی کا عمل، سادنہ علاج کے خصوصی ضوابط، بین الاقوامی طبی منصوبے وغیرہ ترتیب دی جا سکتے ہیں</td></tr><tr><td>E14</td><td>سماجی تحفظ اور فلاحی نظام</td><td>عمر رسیدہ، بے روزگاری، امداد وغیرہ سمیت سمبیوسس تہذیب کے سماجی تحفظ کے نظام کی تفصیلی ترتیب</td><td>دستاویز 32، دستاویز 08</td><td>فلاحی درخواست کی شرائط، تقسیم کے معیار، فنڈز کے ذرائع، نگرانی کے طریقہ کار وغیرہ ترتیب دی جا سکتے ہیں</td></tr></tbody></table><h2 id="_5-قانونی-اور-انتظامی-توسیع-کی-سمت" tabindex="-1">5. قانونی اور انتظامی توسیع کی سمت <a class="header-anchor" href="#_5-قانونی-اور-انتظامی-توسیع-کی-سمت" aria-label="Permalink to &quot;5. قانونی اور انتظامی توسیع کی سمت&quot;">​</a></h2><table tabindex="0"><thead><tr><th>نمبر</th><th>توسیع کی سمت</th><th>توسیع کی قدر</th><th>متعلقہ ترتیب</th><th>تخلیقی تجویز</th></tr></thead><tbody><tr><td>E15</td><td>نمائندہ قانونی مقدمات</td><td>سمبیوسس عدالت کے فیصلہ کردہ نمائندہ مقدمات لکھنا، عمل میں قانون کے اطلاق کو ظاہر کرنا</td><td>دستاویز 40-49، دستاویز 92</td><td>&quot;سادنہ وسائل کی اجارہ داری کا مقدمہ&quot;، &quot;بین الاقوامی آلودگی کی معاوضے کا مقدمہ&quot;، &quot;تاریکی کے متبادل جسم کے حقوق کا مقدمہ&quot; جیسے نمائندہ مقدمات لکھے جا سکتے ہیں</td></tr><tr><td>E16</td><td>مقامی خود مختاری کا نظام</td><td>آئین کے فریم ورک کے اندر ہر ستارہ کے علاقے اور ہر سطح کے خود مختاری کے نظام اور اختیارات کی تقسیم کی تفصیلی ترتیب</td><td>دستاویز 40، دستاویز 49</td><td>مختلف خود مختاری اکائیوں کے خود مختاری کے ماڈل، مرکزی حکومت کے ساتھ تعلق، خود مختاری کے ضوابط کی تیاری کا عمل وغیرہ ترتیب دی جا سکتے ہیں</td></tr><tr><td>E17</td><td>انتخابات اور جمہوری نظام</td><td>اینکر کونسل کے نمائندوں کے انتخابی نظام اور جمہوری فیصلے کے طریقہ کار کی تفصیلی ترتیب</td><td>دستاویز 32، دستاویز 49</td><td>انتخابی حلقوں کی تقسیم، امیدواروں کی اہلیت، انتخابی عمل، ووٹنگ کا طریقہ، مدت کا نظام وغیرہ ترتیب دی جا سکتے ہیں</td></tr><tr><td>E18</td><td>قانون کے نفاذ کا طریقہ کار</td><td>قانون کے نفاذ کے طریقہ کار کی تفصیلی ترتیب، بشمول قانون نافذ کرنے والے ادارے، عمل درآمد، زبردستی اقدامات</td><td>دستاویز 48، دستاویز 49</td><td>قانون نافذ کرنے والے ادارے کی تنظیمی ساخت، قانون کے نفاذ کے اختیارات، عمل درآمد، نگرانی کے طریقہ کار وغیرہ ترتیب دی جا سکتے ہیں</td></tr></tbody></table><h2 id="_6-زندگی-اور-نسلوں-کی-توسیع-کی-سمت" tabindex="-1">6. زندگی اور نسلوں کی توسیع کی سمت <a class="header-anchor" href="#_6-زندگی-اور-نسلوں-کی-توسیع-کی-سمت" aria-label="Permalink to &quot;6. زندگی اور نسلوں کی توسیع کی سمت&quot;">​</a></h2><table tabindex="0"><thead><tr><th>نمبر</th><th>توسیع کی سمت</th><th>توسیع کی قدر</th><th>متعلقہ ترتیب</th><th>تخلیقی تجویز</th></tr></thead><tbody><tr><td>E19</td><td>ایک نسل کی تفصیلی ترتیب</td><td>تمام نسلوں کی فہرست میں سے کسی ایک نسل کو تفصیل سے وسعت دینا، بشمول جسمانی خصوصیات، سماجی ساخت، ثقافتی روایات، تاریخی ارتقاء</td><td>دستاویز 50-52، دستاویز 94</td><td>تجویز ہے کہ پہلے ڈریگن نسل، یلغار نسل، مکینیکل نسل، شعور والی نسل جیسی خصوصیت والی نسلوں کو وسعت دی جائے؛ ہر نسل میں زبان، مذہب، فن، رسم و رواج وغیرہ شامل ہو سکتے ہیں</td></tr><tr><td>E20</td><td>عجیب زندگی کے مخصوص کیسز</td><td>مخصوص عجیب زندگی کے افراد یا گروہوں کی ترتیب، تین قسم کے طریقہ کار کے عملی اطلاق کو ظاہر کرنا</td><td>دستاویز 53-54</td><td>&quot;خلا میں بہنے والے&quot;، &quot;وقت کے ٹکڑوں کی زندگی&quot;، &quot;قانون کے پرجیوی جسم&quot; جیسے عجیب زندگی کے کیسز ترتیب دی جا سکتے ہیں</td></tr><tr><td>E21</td><td>عجیب توانائی کی مخصوص اقسام</td><td>مختلف عجیب توانائیوں کی خصوصیات، ذرائع، استعمال اور کنٹرول کے طریقوں کی تفصیلی ترتیب</td><td>دستاویز 55-56</td><td>&quot;وجہ توانائی&quot;، &quot;شعور توانائی&quot;، &quot;وقت کی گونج توانائی&quot; جیسی عجیب توانائی کی اقسام ترتیب دی جا سکتی ہیں</td></tr><tr><td>E22</td><td>تاریکی کے متبادل جسم کے مخصوص کیسز</td><td>مخصوص تاریکی کے متبادل جسم کی انفرادی کہانیوں کی ترتیب، دوہری روح کی اخلاقیات اور چار قسم کے شاخوں کے طریقہ کار کے عملی اطلاق کو ظاہر کرنا</td><td>دستاویز 57-59</td><td>مختلف قسم کے تاریکی کے متبادل جسم کے کیسز کی کہانیاں لکھی جا سکتی ہیں، دوہری روح کی مشترکہ زندگی کے اخلاقی مخمصے پر بحث کی جا سکتی ہے</td></tr><tr><td>E23</td><td>بین الاقوامی امتزاج کی اولادیں</td><td>مختلف نسلوں کی شادی سے پیدا ہونے والی مخلوط نسلوں کی خصوصیات اور ثقافت کی ترتیب</td><td>دستاویز 52، دستاویز 77</td><td>&quot;نیم یلغار&quot;، &quot;ڈریگن انسان&quot;، &quot;مکینیکل بائیو انسان&quot; جیسی مخلوط نسلیں ترتیب دی جا سکتی ہیں، ان کی شناخت اور ثقافتی امتزاج پر بحث کی جا سکتی ہے</td></tr></tbody></table><h2 id="_7-ٹیکنالوجی-اور-توانائی-کی-توسیع-کی-سمت" tabindex="-1">7. ٹیکنالوجی اور توانائی کی توسیع کی سمت <a class="header-anchor" href="#_7-ٹیکنالوجی-اور-توانائی-کی-توسیع-کی-سمت" aria-label="Permalink to &quot;7. ٹیکنالوجی اور توانائی کی توسیع کی سمت&quot;">​</a></h2><table tabindex="0"><thead><tr><th>نمبر</th><th>توسیع کی سمت</th><th>توسیع کی قدر</th><th>متعلقہ ترتیب</th><th>تخلیقی تجویز</th></tr></thead><tbody><tr><td>E24</td><td>ایک واحد ٹیکنالوجی کی تفصیلی اصول</td><td>کسی ایک کلیدی ٹیکنالوجی (جیسے کاپی آئینہ، الگ تھلگ جگہ، بئی زینگ پھل کی انجینئرنگ) کی تفصیلی اصولوں کا تجزیہ</td><td>دستاویز 60-69، دستاویز 63-64</td><td>ٹیکنالوجی کی ترقی کی تاریخ، بنیادی اجزاء، کام کا عمل، ٹیکنالوجی کی حدود، اپ گریڈ کی سمت وغیرہ ترتیب دی جا سکتی ہے</td></tr><tr><td>E25</td><td>سادنہ کے آلات کی تفصیلی درجہ بندی</td><td>مختلف سادنہ معاون آلات کی درجہ بندی، افعال، درجہ بندی اور استعمال کے طریقوں کی ترتیب</td><td>دستاویز 61، دستاویز 67</td><td>&quot;سادنہ کی کبن&quot;، &quot;قانون کا پتہ لگانے والا آلہ&quot;، &quot;توانائی کا کنورٹر&quot;، &quot;شعور کا بڑھانے والا آلہ&quot; جیسی آلات کی اقسام ترتیب دی جا سکتی ہیں</td></tr><tr><td>E26</td><td>اینکر ہارڈویئر کی تفصیلی ترتیب</td><td>اینکر ہارڈویئر کی سہولیات کے ڈھانچے، افعال، تعمیر اور دیکھ بھال کی تفصیلی ترتیب</td><td>دستاویز 20، دستاویز 67</td><td>مصنوعی اینکر کے بنیادی اجزاء، توانائی کی فراہمی، دیکھ بھال کا چکر، خرابی کا علاج وغیرہ ترتیب دی جا سکتے ہیں</td></tr><tr><td>E27</td><td>بین الاقوامی مواصلاتی ٹیکنالوجی</td><td>بین الاقوامی مواصلاتی ٹیکنالوجی کے اصولوں، آلات کی اقسام، مواصلاتی پروٹوکول اور حفاظتی طریقہ کار کی تفصیلی ترتیب</td><td>دستاویز 66، دستاویز 81</td><td>&quot;اینکر لہر مواصلات&quot;، &quot;خلائی تہہ مواصلات&quot;، &quot;شعور گونج مواصلات&quot; جیسے مختلف مواصلاتی طریقے ترتیب دی جا سکتے ہیں</td></tr></tbody></table><h2 id="_8-تاریخی-اور-واقعات-کی-توسیع-کی-سمت" tabindex="-1">8. تاریخی اور واقعات کی توسیع کی سمت <a class="header-anchor" href="#_8-تاریخی-اور-واقعات-کی-توسیع-کی-سمت" aria-label="Permalink to &quot;8. تاریخی اور واقعات کی توسیع کی سمت&quot;">​</a></h2><table tabindex="0"><thead><tr><th>نمبر</th><th>توسیع کی سمت</th><th>توسیع کی قدر</th><th>متعلقہ ترتیب</th><th>تخلیقی تجویز</th></tr></thead><tbody><tr><td>E28</td><td>اہم تاریخی واقعات کی تفصیلی بیان</td><td>کرونیکل میں سے کسی ایک اہم واقعے کی تفصیلی تاریخی بیان</td><td>دستاویز 70-79، دستاویز 93</td><td>&quot;تین سو نظام کھولنے کا واقعہ&quot;، &quot;20% ایکٹیویشن کی حکمت عملی کا نفاذ&quot;، &quot;پہلی جہت بڑھانے کا سنگ میل&quot; جیسے واقعات کے مکمل عمل کو تفصیل سے بیان کیا جا سکتا ہے</td></tr><tr><td>E29</td><td>تاریخی شخصیات کی سوانح عمریں</td><td>کلیدی شخصیات کے لیے تفصیلی سوانح عمریں لکھنا، تاریخ کی انسانی گہرائی کو بھرپور بنانا</td><td>دستاویز 95</td><td>&quot;شوان ہینگ زی&quot;، &quot;گونگ شینگ زی&quot;، &quot;لی شیانگ گونگ&quot;، &quot;سان بائی شی&quot; جیسی کلیدی شخصیات کے لیے سوانح عمریں لکھی جا سکتی ہیں</td></tr><tr><td>E30</td><td>تاریخی موڑ کے مفروضے کا تجزیہ</td><td>تجزیہ کرنا کہ اگر کوئی تاریخی واقعہ مختلف سمت میں چلا جاتا تو سمبیوسس تہذیب کی ترقی کس طرح مختلف ہوتی</td><td>دستاویز 70-79</td><td>&quot;اگر سمبیوسس آئین منظور نہ ہوتا&quot;، &quot;اگر 20% ایکٹیویشن کی حکمت عملی ناکام ہو جاتی&quot; جیسے مفروضے کے تجزیے کیے جا سکتے ہیں، تاریخ کے اتفاقیت کو ظاہر کرتے ہوئے</td></tr><tr><td>E31</td><td>آثار قدیمہ کی دریافت کی تفصیلی ریکارڈ</td><td>کسی ایک بین الاقوامی آثار قدیمہ کی تفصیلی دریافت اور تحقیقی نتائج کی ترتیب</td><td>دستاویز 84-87</td><td>&quot;کسی کھوئی ہوئی تہذیب کی آثار قدیمہ کی دریافت&quot;، &quot;کسی کلیدی تاریخی نوڈ کی وقت کی تکرار آثار قدیمہ کے نتائج&quot; جیسے ترتیب دی جا سکتے ہیں</td></tr></tbody></table><h2 id="_9-بین-الاقوامی-اور-وقت-کی-توسیع-کی-سمت" tabindex="-1">9. بین الاقوامی اور وقت کی توسیع کی سمت <a class="header-anchor" href="#_9-بین-الاقوامی-اور-وقت-کی-توسیع-کی-سمت" aria-label="Permalink to &quot;9. بین الاقوامی اور وقت کی توسیع کی سمت&quot;">​</a></h2><table tabindex="0"><thead><tr><th>نمبر</th><th>توسیع کی سمت</th><th>توسیع کی قدر</th><th>متعلقہ ترتیب</th><th>تخلیقی تجویز</th></tr></thead><tbody><tr><td>E32</td><td>ایک مخصوص سطح کی تفصیلی ترتیب</td><td>کسی ایک مخصوص سطح کے قانون کے پیرامیٹرز، تہذیب کی شکل، جغرافیائی ماحول اور تاریخ کی ترتیب</td><td>دستاویز 80، دستاویز 81</td><td>&quot;اعلیٰ جادو کی سطح&quot;، &quot;ٹیکنالوجی کی سطح&quot;, &quot;جنگلی سطح&quot;، &quot;شعور کی سطح&quot; جیسی مختلف قسم کی مخصوص سطحیں ترتیب دی جا سکتی ہیں</td></tr><tr><td>E33</td><td>بین الاقوامی سفارت کاری کے کیسز</td><td>سمبیوسس تہذیب اور دوسری سطح کی تہذیبوں کے درمیان سفارتی تعلقات قائم کرنے کے مخصوص کیسز کی ترتیب</td><td>دستاویز 81، دستاویز 88</td><td>پہلی رابطہ، سفارتی مذاکرات، ثقافتی تبادلہ، تجارتی معاہدے جیسے مخصوص سفارتی واقعات ترتیب دی جا سکتے ہیں</td></tr><tr><td>E34</td><td>وقت کی تکرار کے مخصوص کیسز</td><td>کسی ایک وقت کی تکرار کے آپریشن کے مخصوص عمل، دریافت اور اثرات کی ترتیب</td><td>دستاویز 82-83، دستاویز 89</td><td>&quot;کسی تاریخی معمہ کی تکرار سے حل&quot;، &quot;کسی معدوم تہذیب کی تکرار سے بحالی&quot; جیسے کیسز ترتیب دی جا سکتے ہیں</td></tr><tr><td>E35</td><td>وقت کے تضاد کے واقعے کی تفصیلی ریکارڈ</td><td>کسی ایک وقت کے تضاد کے واقعے کے واقع، ہنگامی ردعمل اور وجہ کی مرمت کے مکمل عمل کی ترتیب</td><td>دستاویز 89</td><td>ایک چھوٹے پیمانے پر تضاد کے واقعے کی مکمل طریقہ کار کی ریکارڈ لکھی جا سکتی ہے، روک تھام کے طریقہ کار کے عملی کام کو ظاہر کرتے ہوئے</td></tr><tr><td>E36</td><td>بین الاقوامی تنازعات اور حل</td><td>سمبیوسس تہذیب اور دوسری سطح کی تہذیبوں کے درمیان تنازعات اور ان کے امن حل کے عمل کی ترتیب</td><td>دستاویز 81، دستاویز 88</td><td>وسائل کا تنازعہ، ثقافتی تصادم، سرحدی جھگڑا جیسے مختلف قسم کے بین الاقوامی تنازعات کے کیسز ترتیب دی جا سکتے ہیں</td></tr></tbody></table><h2 id="_10-توسیعی-ترتیبات-کی-تخلیقی-اصول" tabindex="-1">10. توسیعی ترتیبات کی تخلیقی اصول <a class="header-anchor" href="#_10-توسیعی-ترتیبات-کی-تخلیقی-اصول" aria-label="Permalink to &quot;10. توسیعی ترتیبات کی تخلیقی اصول&quot;">​</a></h2><p>توسیعی ترتیب کی تخلیق کرتے وقت، درج ذیل اصولوں پر عمل کرنا چاہیے:</p><ol><li><strong>مطابقت کو ترجیح دیں</strong>: تمام توسیعی ترتیبات کو موجودہ ترتیبات کے ساتھ منطقی مطابقت برقرار رکھنی ہوگی، اور ترتیب کے تضاد کی خود جانچ کی جدول کی جانچ پاس کرنی ہوگی۔</li><li><strong>حقیقت پر مبنی</strong>: توسیعی ترتیبات کو معقول تخمین کے لیے مقامی قوانین پر مبنی ہونا چاہیے، خالص خیال اور ترتیب کے ٹوٹنے سے بچنا چاہیے۔</li><li><strong>سمبیوسس کا موقف</strong>: توسیعی ترتیبات کو ہمیشہ لوٹ مار کے خلاف اور سمبیوسس کی وکالت کے بنیادی موقف پر قائم رہنا چاہیے، لوٹ مار کے رویے کی حمایت نہیں کرنی چاہیے۔</li><li><strong>کھلا پن</strong>: توسیعی ترتیبات کو ایک خاص حد تک کھلا پن برقرار رکھنا چاہیے، مستقبل میں مزید توسیع کے لیے جگہ محفوظ رکھنی چاہیے۔</li><li><strong>عملییت</strong>: توسیعی ترتیبات میں عملی تخلیقی قدر ہونی چاہیے، جو کہانی کی تخلیق، گیم ڈیزائن اور نظریاتی بحث کے لیے مفید مواد فراہم کرنے کے قابل ہو۔</li></ol><h2 id="اختتامیہ" tabindex="-1">اختتامیہ <a class="header-anchor" href="#اختتامیہ" aria-label="Permalink to &quot;اختتامیہ&quot;">​</a></h2><p>توسیعی ترتیبات کی تجاویز کی فہرست اینکر سمبیوسس تہذیب کے ترتیب کے نظام کا &quot;کھلا دروازہ&quot; ہے۔ یہ ظاہر کرتی ہے کہ یہ ترتیب کا نظام ایک بند، مکمل حالت کی مصنوعات نہیں ہے، بلکہ ایک مسلسل بڑھتا ہوا، مسلسل بھرپور ہوتا ہوا زندہ نظام ہے۔ چھتیس توسیعی سمتیں صرف آغاز کا نقطہ ہیں۔ حقیقی ترتیب کی تخلیقی صلاحیت ہر شریک کے تخیل اور جوش سے پیدا ہوتی ہے۔ جب تک ترتیب کی مطابقت کے بنیادی اصولوں پر عمل کیا جاتا ہے، ہر قیمتی توسیع اینکر سمبیوسس تہذیب کے شاندار افسانے میں ایک لازمی حصہ بن جائے گی۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>97-ترتیبات کے تضاد کی خود جانچ کی جدول</li><li>99-دستاویز کا ورژن اور دیکھ بھال کی ہدایات</li><li>96-عام سوالات FAQ</li></ul>',27)])])}const _=d(h,[["render",e]]);export{s as __pageData,_ as default};
